    /// <param name="transfer">How ownership of <paramref name="handle"/> is transferred.</param>
    /// <returns>The new wrapper.</returns>
    internal static object CreateWrapper(nint handle, Gst.Interop.Transfer transfer) => new Concrete(handle, transfer);

    /// <summary>
    /// The wrapper of a native type that derives from <c>GstObject</c> and has no
    /// generated binding of its own, for example an element of a plugin.
    /// </summary>
    private sealed class Concrete : Object
    {
        /// <summary>Wraps a native instance.</summary>
        /// <param name="handle">The native instance.</param>
        /// <param name="transfer">How ownership of <paramref name="handle"/> is transferred.</param>
        internal Concrete(nint handle, Gst.Interop.Transfer transfer)
            : base(handle, transfer)
        {
        }
    }
}
